STYLE = """
:root{color-scheme:light dark;--bg:#f7f7f5;--fg:#1d1d1f;--muted:#62666a;--line:#dededb;--card:#fff;--acc:#225fc1;--warn:#856000;--bad:#b63028;--ok:#21663e}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.65 system-ui,sans-serif;overflow-wrap:anywhere}a{color:var(--acc)}button,a,summary{touch-action:manipulation}button{font:inherit;color:inherit;background:var(--card);border:1px solid var(--line);border-radius:8px;padding:8px 12px;min-height:44px;cursor:pointer}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--acc);outline-offset:3px}
.top{position:sticky;top:0;z-index:5;background:var(--card);border-bottom:1px solid var(--line);padding:10px 16px;display:flex;gap:12px;align-items:center;flex-wrap:wrap}.brand{font-weight:750;color:var(--fg)}nav{display:flex;gap:12px;align-items:center;flex-wrap:wrap}nav a{padding:8px 0}.language{margin-left:auto;display:flex;gap:4px}main,footer{max-width:1080px;margin:auto;padding:20px 16px}footer,.muted{color:var(--muted)}h1{font-size:clamp(24px,5vw,36px);line-height:1.2}h2{font-size:21px}h3{font-size:18px}h4{margin:8px 0}p{margin:8px 0}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:14px}.card,.fold,.callout{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px;margin:12px 0}.card h3{margin-top:0}.daycard{border-top:4px solid var(--acc)}.callout{border-left:4px solid var(--acc)}.fold>summary{cursor:pointer;min-height:44px}.fold>summary h2{display:inline}.meta{font-size:14px;color:var(--muted)}.badge{display:inline-block;padding:2px 8px;border-radius:8px;background:var(--bg);font-size:13px;font-weight:600}.badge.pending{color:var(--warn)}.badge.confirmed{color:var(--ok)}.badge.not_used{color:var(--muted)}.memory{border-top:1px solid var(--line);padding:6px 0}.passed{color:var(--ok)}.unverified{color:var(--warn)}.conflict{color:var(--bad)}.check{border-left:3px solid currentColor;margin:10px 0;padding-left:12px}.check p{font-size:14px;color:var(--fg)}.tracks{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:12px}.timeline{list-style:none;padding:0}.timeline>li{border-left:3px solid var(--acc);padding:10px 12px;margin:10px 0;background:var(--bg);border-radius:0 8px 8px 0}.time{font-weight:750;font-variant-numeric:tabular-nums}.place-name{display:block;user-select:all;font-weight:650}.place-note{display:block;font-size:14px}.copy{margin:6px 0}dl{display:grid;grid-template-columns:auto 1fr;gap:8px 16px}dt{font-weight:650}dd{margin:0;white-space:pre-wrap}.daylist li{padding:8px 0}.foldbar{display:flex;gap:8px;margin:12px 0}.result-material{white-space:pre-wrap}.daynavs{display:flex;justify-content:space-between;gap:16px}.navtoggle{display:none}.empty{color:var(--muted)}[hidden]{display:none!important}
html[data-language=zh] .en,html[data-language=en] .zh{display:none}html[data-language=zh] .zh,html[data-language=en] .en{white-space:normal}
@media(max-width:600px){.top{position:static}.navtoggle{display:block}nav{display:none;flex-basis:100%}.navopen nav{display:flex}.language{margin-left:0}main{padding:12px}dl{grid-template-columns:1fr;gap:2px}dd{margin-bottom:10px}.card,.fold{padding:12px}}
@media(prefers-color-scheme:dark){:root{--bg:#171a1c;--fg:#e7e8e9;--muted:#adb2b7;--line:#393f43;--card:#23272a;--acc:#8dbaff;--warn:#f0c760;--bad:#ff9690;--ok:#8cdbac}}
"""

SCRIPT = """
(()=>{const root=document.documentElement;const setLanguage=language=>{if(!['zh','en'].includes(language))return;root.dataset.language=language;root.lang=language==='zh'?'zh-CN':'en';document.querySelectorAll('[data-language-button]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.languageButton===language)));document.querySelectorAll('a[data-language-link]').forEach(link=>{const url=new URL(link.href,location.href);url.searchParams.set('lang',language);link.href=url.href;});};setLanguage(new URLSearchParams(location.search).get('lang')||root.dataset.language);document.querySelectorAll('[data-language-button]').forEach(button=>button.addEventListener('click',()=>setLanguage(button.dataset.languageButton)));document.querySelectorAll('[data-fold]').forEach(button=>button.addEventListener('click',()=>document.querySelectorAll('details.fold').forEach(detail=>detail.open=button.dataset.fold==='open')));document.querySelector('[data-menu]')?.addEventListener('click',event=>{document.body.classList.toggle('navopen');event.currentTarget.setAttribute('aria-expanded',String(document.body.classList.contains('navopen')));});document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.dataset.copy);button.textContent=root.dataset.language==='zh'?'已复制':'Copied';}catch(error){const selection=getSelection();const range=document.createRange();range.selectNodeContents(button.previousElementSibling);selection.removeAllRanges();selection.addRange(range);}}));})();
"""
